using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "ConfigMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { EnableCaching = true, EnableLogging = true }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Gets the value of a configuration setting by key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g., 'AppName', 'MaxRetries')")] string key)
    {
        var settings = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["AppName"] = "ConfigMcpServer",
            ["Version"] = "1.0.0",
            ["MaxRetries"] = "3",
            ["TimeoutSeconds"] = "30"
        };

        return settings.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Unknown configuration key: '{key}'";
    }

    [McpServerTool, Description("Lists all available configuration keys.")]
    public static string ListConfigKeys()
    {
        return string.Join("\n", "AppName", "Version", "MaxRetries", "TimeoutSeconds");
    }
}

